<?php
declare(strict_types=1);
require __DIR__.'/../src/Rules.php';
$rules=new AceTR\Rules();$data=$rules->data();$labels=['Saldırı','Savunma','Yakıt','Ruh / SP','Kalkan','Kaçınma'];
$gear=is_string($_GET['gear']??null)?$_GET['gear']:'BGEAR';
$level=filter_var($_GET['level']??1,FILTER_VALIDATE_INT);$level=$level===false?1:max(1,min(110,$level));
if(!isset($data['gears'][$gear]))$gear='BGEAR';
$stats=[];for($i=0;$i<6;$i++){$v=filter_var($_GET['s'.$i]??3,FILTER_VALIDATE_INT);$stats[]=$v===false?3:max(0,min(65535,$v));}
$result=$rules->calculate($gear,$level,$stats);function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="tr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AceTR — Özgün Stat Motoru</title><style>body{background:#090f1b;color:#e0edf7;font:15px system-ui;max-width:1000px;padding:35px 20px;margin:auto}h1{font-size:32px}p{color:#95a9bf;line-height:1.7}a{color:#6fe2ed}form,.result{background:#142032;padding:25px;border:1px solid #2b4055;border-radius:8px;margin:25px 0}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:15px}label{display:block;color:#8ca8bd}input,select{box-sizing:border-box;display:block;width:100%;padding:12px;background:#0a1524;color:#fff;border:1px solid #3c5266;border-radius:4px;margin-top:8px}button{margin-top:24px;padding:14px 24px;background:#6fe2ed;border:0;border-radius:4px;font-weight:bold;cursor:pointer}.result{display:grid;grid-template-columns:repeat(auto-fit,minmax(175px,1fr));gap:24px}.result strong{display:block;font-size:26px;color:#6fe2ed}small{color:#829bb1}</style><div style="color:#6fe2ed;letter-spacing:3px">ACETR / KAYNAKTAN AKTARIM</div><h1>AirRivals stat motoru</h1><p>ProRivalsSrc içindeki gerçek tablolarla hesaplanan temel değerler. Bu ekran bir hesaplayıcıdır; henüz tam oyun değildir. Profil: S_CAN_SERVER_SETTING_HSSON.</p><form><div class="fields"><label>Gemi<select name="gear"><?php foreach($data['gears'] as $g=>$v):?><option <?= $g===$gear?'selected':'' ?>><?= e($g) ?></option><?php endforeach?></select></label><label>Pilot seviyesi<input type="number" name="level" min="1" max="110" value="<?= $level ?>"></label></div><h2>Stat değerleri</h2><div class="fields"><?php foreach($labels as $i=>$label):?><label><?= e($label) ?><input name="s<?= $i ?>" type="number" min="0" max="65535" value="<?= $stats[$i] ?>"><small>1 puan: +<?= $data['gears'][$gear][$i] ?></small></label><?php endforeach?></div><button>Değerleri hesapla →</button></form><div class="result"><?php foreach(['hp'=>'HP','shield'=>'Kalkan / DP','sp'=>'SP','fuel'=>'Yakıt / EP','attackRate'=>'Saldırı artışı','hitBonus'=>'İsabet bonusu (ham)','pierce'=>'Pierce (ham)','defenseRate'=>'Savunma oranı','dodgeRate'=>'Kaçınma oranı','cap'=>'Stat üst sınırı'] as $key=>$label):?><div><small><?= e($label) ?></small><strong><?= e(in_array($key,['attackRate','defenseRate','dodgeRate'],true)?round($result[$key]*100,4).'%':$result[$key]) ?></strong></div><?php endforeach?></div><p>İsabet ve Pierce ham kaynak değerleridir; nihai savaş olasılığı değildir. Eşya, skill, buff ve hedef etkileri bu hesaplayıcıya dahil değildir. Seviye başlangıç deneyimi: <?= e($rules->initialExperience($level)) ?>.</p><small>Kaynak commit: <?= e($data['source']['commit']) ?></small></html>
